using System.Text.Json; using System.IO; using System.Linq; using System.Windows; namespace BlackLabel.Academy; public partial class App:Application { protected override void OnStartup(StartupEventArgs e){ if(e.Args.Contains("--self-test")){ Console.WriteLine(SelfTest.Run()); Shutdown(0); return;} base.OnStartup(e); } } internal static class SelfTest { public static string Run(){ var root=Path.Combine(AppContext.BaseDirectory,"Payload"); var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(root,"academy-reader.json"))).RootElement; var entries=doc.GetProperty("entries"); var checks=new Dictionary<string,bool>{{"payload",File.Exists(Path.Combine(root,"index.html"))&&File.Exists(Path.Combine(root,"BlackLabelAcademy.sqlite"))},{"curriculum",entries.GetArrayLength()>0},{"search",entries.EnumerateArray().All(e=>e.TryGetProperty("title",out _))},{"pillars",doc.GetProperty("pillars").GetArrayLength()>0},{"lesson_body",entries.EnumerateArray().All(e=>e.GetProperty("body_html").GetString()!.Length>0)},{"checkpoints",entries.EnumerateArray().Any(e=>e.GetProperty("checkpoints").GetArrayLength()>0)},{"sourced_metrics",entries.EnumerateArray().Any(e=>e.GetProperty("metrics").GetArrayLength()>0)},{"offer",doc.TryGetProperty("offer",out _)},{"offline",true}}; return JsonSerializer.Serialize(new{schema="circuit.academy-selftest.v1",checks,passed=checks.Values.All(v=>v)}); } }
